values ('dialog_fq_arc_031', 'fq_arc_031', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Scholar! The Observatory has been recording unusual patterns. The Arcanum Seekers require access to orbital platforms", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Glass Archive: Witness at the Ridge 02. In Shard Pulse Peak: Defeat 6 SHARD_PULSE_SENTINEL. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 257)
