values ('dialog_fq_arc_068', 'fq_arc_068', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. Aethel Rift Stalkers create micro-rifts that offer glimpses into alternate ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Knowledge demands risk. The Concordium wants to regulate the Shard. The Hegemony wants to weaponize it. We want to understand it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Severance Proof: A Narrow Passage 04. In Shattered Heart: Defeat 9 DRAKE_MINION. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 294)
