values ('dialog_fq_arc_100', 'fq_arc_100', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. You have done the impossible", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Prima Materia Thesis: Report to Command 05. In Eternal Gate: Defeat 1 ABYSS_HARBINGER. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 326)
