values ('dialog_fq_iron_006', 'fq_iron_006', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. The Ravine Is Ours Now — The Iron Ravine sits on mineral deposits that could supply the Bastion''s fo...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Supply Discipline: The Missing Patrol 01. In Scrap Field: Defeat 3 SCRAP_CRAWLER. Hold the line and report the condition of the route when the work is done.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 332)
