values ('dialog_fq_iron_018', 'fq_iron_018', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. Deep in the War Machine Graveyard''s protected core zone, a Sentinel Commander", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Supply Discipline: The Unquiet Machine 01. In War Machine Graveyard: Defeat 4 WAR_MACHINE_WRECKER. Hold the line and report the condition of the route when the work is done.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 344)
